import torch
from torch import nn
class Regressor(nn.Module):
    def __init__(self):
        super().__init__(); self.layers = nn.Sequential(nn.Linear(4, 8), nn.ReLU(), nn.Linear(8, 1))
    def forward(self, x): return self.layers(x)
print(Regressor()(torch.ones(3, 4)).shape)

